record.field:
MARKER = 'ST_JORDI_TAX_FIX_APPLIED'
PRODUCT_TMPL_ID = 9067
TAX_PER_UNIT = 0.41
SUBTOTAL_PER_UNIT = 4.09

for order in records:
    # Barrera de idempotencia: ¿ya se procesó este pedido?
    if order.note and MARKER in order.note:
        continue

    lines_to_fix = order.lines.filtered(
        lambda l: (not l.tax_ids
                   and l.product_id.product_tmpl_id.id == PRODUCT_TMPL_ID
                   and l.product_id.taxes_id)
    )

    if lines_to_fix:
        for line in lines_to_fix:
            line.write({
                'tax_ids': [(6, 0, line.product_id.taxes_id.ids)],
                'price_subtotal': line.qty * SUBTOTAL_PER_UNIT,
            })

        total_tax_adjustment = sum(line.qty * TAX_PER_UNIT for line in lines_to_fix)
        order.write({'amount_tax': order.amount_tax + total_tax_adjustment})

        # Marcar el pedido como procesado (preservando nota existente)
        new_note = f'{MARKER}: ajuste IVA St. Jordi (+{total_tax_adjustment:.2f} €)'
        if order.note:
            new_note = order.note + '\n' + new_note
        order.write({'note': new_note})
